import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { nowIso, openDatabase, rowToJob, transaction, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 1_000_000;
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const HEARTBEAT_FRESH_MS = 3_000;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
}

/** Reads the request body as UTF-8. Resolves to null when it exceeds the limit (the rest is drained). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function mediaType(header: string | undefined): string {
  return (header ?? '').split(';')[0]!.trim().toLowerCase();
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isInRange(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates a submission body and applies defaults. Collects every problem into `fields`. */
function validateSubmission(text: string | null, idempotencyKey: string | undefined, fields: FieldError[]): Submission | undefined {
  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  if (text === null) {
    fields.push({ field: 'body', message: 'body exceeds 1 MB' });
    return undefined;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return undefined;
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return undefined;
  }
  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }
  const { input, steps = 5, failAttempts = 0 } = parsed;
  if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'must be a non-blank string of 1 to 1000 characters' });
  }
  if (!isInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  if (!isInRange(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  if (fields.length > 0 || typeof input !== 'string' || !isInRange(steps, 1, 20) || !isInRange(failAttempts, 0, 5)) return undefined;
  return { input, steps, failAttempts };
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  if (mediaType(req.headers['content-type']) !== 'application/json') {
    sendError(res, 400, 'invalid_request', 'Content-Type must be application/json.', [
      { field: 'body', message: 'Content-Type must be application/json' },
    ]);
    await readBody(req);
    return;
  }
  const text = await readBody(req);
  const idempotencyKey = req.headers['idempotency-key'];
  const fields: FieldError[] = [];
  const submission = validateSubmission(text, idempotencyKey, fields);
  if (!submission) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
    return;
  }

  // Canonical payload with fixed key order, after defaults: used to compare idempotent replays.
  const payload = JSON.stringify({ input: submission.input, steps: submission.steps, failAttempts: submission.failAttempts });
  const outcome = transaction(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        return existing.payload === payload ? { conflict: false, row: existing } : { conflict: true, row: existing };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after,
                         idempotency_key, payload, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, idempotencyKey ?? null, payload, now, now);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow;
    return { conflict: false, row, created: true };
  });

  if (outcome.conflict) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, 'created' in outcome ? 201 : 200, rowToJob(outcome.row));
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGetOne(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  send(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1').get() as { last_seen: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.last_seen < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const path = (req.url ?? '/').split('?')[0]!;
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(path);

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleHealth(res);
  }
  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (path === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res);
  }
  if (jobMatch) {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleGetOne(res, jobMatch[1]!);
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

