import { setInterval as every, clearInterval } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const TRANSIENT_ERROR = 'transient failure';

const db = openDatabase();
let stopping = false;
/** The job this process is currently running, if any. */
let currentJobId: string | undefined;

function writeHeartbeat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, last_seen) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen',
  ).run(Date.now());
}

// A job left 'running' by a worker that died is put back in the queue. The interrupted attempt is
// re-run with the same attempt number (resume = 1), so `attempts` never counts it twice.
// Only one worker runs at a time, so no other process can be holding one of these jobs.
transaction(db, () => {
  db.prepare(
    "UPDATE jobs SET status = 'queued', resume = 1, progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
  ).run(nowIso());
});

writeHeartbeat();
const heartbeatTimer = every(writeHeartbeat, HEARTBEAT_MS);

/** Claims the oldest due queued job and returns it with the number of the attempt that is starting. */
function claim(): { job: JobRow; attempt: number } | undefined {
  return transaction(db, () => {
    const job = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as JobRow | undefined;
    if (!job) return undefined;
    const attempt = job.attempts + (job.resume ? 0 : 1);
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = ?, resume = 0, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(attempt, nowIso(), job.id);
    return { job, attempt };
  });
}

async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  currentJobId = job.id;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure, at the first step and before any progress.
    await sleep(STEP_MS);
    if (attempt < MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    } else {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(TRANSIENT_ERROR, nowIso(), job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(step, nowIso(), job.id);
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

async function loop(): Promise<void> {
  while (!stopping) {
    try {
      const next = claim();
      if (!next) {
        await sleep(POLL_MS);
        continue;
      }
      await runAttempt(next.job, next.attempt);
      currentJobId = undefined;
    } catch (err) {
      // Typically SQLITE_BUSY that outlasted busy_timeout. Log and keep going.
      console.error('worker iteration failed:', err);
      currentJobId = undefined;
      await sleep(POLL_MS);
    }
  }
}

/**
 * Synchronous on purpose: no transaction is open while a signal handler runs, so these writes
 * cannot interleave with the loop's writes.
 */
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  clearInterval(heartbeatTimer);
