    // Requeue the interrupted attempt so the next worker re-runs it as the same attempt.
    db.prepare(
      "UPDATE jobs SET status = 'queued', resume = 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(nowIso(), currentJobId);
  }
  db.prepare('UPDATE worker_heartbeat SET last_seen = 0 WHERE id = 1').run();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

console.log('worker started');
void loop();

