// Behaviour tests against the built app. Lives outside the repository.
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const APP = process.argv[2];
const DIR = mkdtempSync(join(tmpdir(), 'jt-'));
const DB = join(DIR, 'nested', 'jobs.db'); // parent dir intentionally missing
const PORT = 3400 + Math.floor(Math.random() * 300);
const BASE = `http://127.0.0.1:${PORT}`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let failures = 0;
function check(name, cond, detail = '') {
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${cond ? '' : ' :: ' + detail}`);
  if (!cond) failures++;
}

function start(which) {
  const child = spawn(process.execPath, ['--disable-warning=ExperimentalWarning', join(APP, 'dist', which + '.js')], {
    env: { ...process.env, PORT: String(PORT), DATABASE_PATH: DB },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  child.stderrText = '';
  child.stderr.on('data', (d) => (child.stderrText += d));
  child.exitedAt = null;
  child.exitPromise = new Promise((r) => child.on('exit', (code, signal) => r({ code, signal, at: Date.now() })));
  return child;
}

async function req(method, path, { body, headers = {} } = {}) {
  const res = await fetch(BASE + path, { method, body, headers });
  const text = await res.text();
  let json;
  try { json = JSON.parse(text); } catch { json = undefined; }
