  await main();
} catch (e) {
  failures++;
  console.log('ERROR', e.message);
} finally {
  for (const p of procs()) p.kill('SIGKILL');
  console.log(`\n${failures === 0 ? 'ALL PASSED' : failures + ' FAILURE(S)'}`);
  if (server) console.log('server stderr:', server.stderrText.slice(-500));
  if (worker) console.log('worker stderr:', worker.stderrText.slice(-500));
  process.exit(failures === 0 ? 0 : 1);
}

