    stdio: ['ignore', 'pipe', 'pipe'],
  });
  child.stderrText = '';
  child.stderr.on('data', (d) => (child.stderrText += d));
  child.exitedAt = null;
  child.exitPromise = new Promise((r) => child.on('exit', (code, signal) => r({ code, signal, at: Date.now() })));
